import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";
import { useState } from "react";

export default function Hero({
  title,
  subtitle,
  ctaHref,
  photoSrc,
  photoAlt,
  badges,
}: {
  title: string;
  subtitle: string;
  ctaHref: string;
  photoSrc: string;
  photoAlt: string;
  badges: string[];
}) {
  const prefersStill = useReducedMotion();
  const [hovered, setHovered] = useState(false);
  const fade = (delay: number) =>
    prefersStill
      ? {}
      : { initial: { opacity: 0, y: 12 }, animate: { opacity: 1, y: 0 }, transition: { duration: 0.5, delay } };

  return (
    <LazyMotion features={domAnimation}>
      <section id="hero" className="relative overflow-hidden bg-background text-foreground">
        {/* мягкая подложка-дуга — единая композиционная идея */}
        <div
          aria-hidden="true"
          className="pointer-events-none absolute -top-24 -right-24 h-[420px] w-[420px] rounded-full border border-border opacity-60"
        />
        <div
          aria-hidden="true"
          className="pointer-events-none absolute top-24 -right-8 h-[300px] w-[300px] rounded-full border border-border opacity-40"
        />

        <div className="mx-auto grid max-w-page grid-cols-1 items-center gap-10 px-gutter py-section lg:grid-cols-2 lg:gap-14">
          <div className="min-w-0">
            {badges.length > 0 && (
              <m.p {...fade(0)} className="mb-4 flex flex-wrap items-center gap-x-3 gap-y-1 text-small text-muted-foreground">
                <span aria-hidden="true" className="inline-block h-2 w-2 rounded-full bg-primary" />
                {badges.join(" · ")}
              </m.p>
            )}

            <m.h1
              {...fade(0.08)}
              className="font-display text-hero leading-tight tracking-tight wrap-break-word text-balance"
            >
              {title}
            </m.h1>

            <m.p {...fade(0.16)} className="mt-6 max-w-text text-lead text-muted-foreground wrap-break-word">
              {subtitle}
            </m.p>

            <m.div {...fade(0.24)} className="mt-8 flex flex-wrap items-center gap-4">
              <a
                href={ctaHref}
                onMouseEnter={() => setHovered(true)}
                onMouseLeave={() => setHovered(false)}
                className="inline-flex min-h-11 items-center justify-center rounded-control bg-primary px-7 text-body font-semibold text-primary-foreground transition-colors hover:bg-scrim"
              >
                Записаться на приём
              </a>
              <a
                href="#features"
                className="inline-flex min-h-11 items-center justify-center rounded-control border border-border px-7 text-body text-foreground transition-colors hover:bg-card hover:text-card-foreground"
              >
                О клинике
              </a>
            </m.div>

            <m.ul {...fade(0.32)} className="mt-8 grid grid-cols-1 gap-2 text-small text-muted-foreground sm:grid-cols-2">
              <li className="flex min-w-0 items-start gap-2">
                <span aria-hidden="true" className="mt-1 inline-block h-1.5 w-1.5 shrink-0 rounded-full bg-primary" />
                Заявки не теряются — каждая попадает к администратору
              </li>
              <li className="flex min-w-0 items-start gap-2">
                <span aria-hidden="true" className="mt-1 inline-block h-1.5 w-1.5 shrink-0 rounded-full bg-primary" />
                Перезвоним в течение 15 минут
              </li>
            </m.ul>
          </div>

          <m.figure
            {...fade(0.2)}
            className="relative min-w-0"
          >
            <div className="overflow-hidden rounded-lg">
              <img
                src={photoSrc}
                alt={photoAlt}
                width={800}
                height={533}
                loading="eager"
                className="aspect-3/2 w-full rounded-lg object-cover"
              />
            </div>
            <figcaption className="mt-3 flex items-center justify-between gap-4 text-small text-muted-foreground">
              <span>{photoAlt}</span>
              <a href="#contacts" className="shrink-0 text-primary underline-offset-4 hover:underline">
                Контакты
              </a>
            </figcaption>
          </m.figure>
        </div>

        {hovered && <span className="sr-only">Кнопка активна</span>}
      </section>
    </LazyMotion>
  );
}

