            <m.p {...fade(0.16)} className="mt-6 max-w-text text-lead text-muted-foreground wrap-break-word">
              {subtitle}
            </m.p>

            <m.div {...fade(0.24)} className="mt-8 flex flex-wrap items-center gap-4">
              <a
                href={ctaHref}
                className="inline-flex min-h-11 items-center justify-center rounded-control bg-primary px-7 text-body font-semibold text-primary-foreground transition-colors hover:bg-scrim hover:text-scrim-foreground"
              >
                Записаться на приём
