            </m.div>

            <m.ul {...fade(0.32)} className="mt-8 grid grid-cols-1 gap-2 text-small text-muted-foreground sm:grid-cols-2">
              <li className="flex min-w-0 items-start gap-2">
                <span aria-hidden="true" className="mt-1 inline-block h-1.5 w-1.5 shrink-0 rounded-full bg-primary" />
                Каждая заявка с сайта попадает к администратору
