import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";
import { useEffect, useState } from "react";

export default function Hero({
  badge,
  title,
  subtitle,
  photo,
  photoAlt,
  primaryAction,
  secondaryAction,
  stat,
}: {
  badge: string;
  title: string;
  subtitle: string;
  photo: string;
  photoAlt: string;
  primaryAction: { href: string; label: string };
  secondaryAction: { href: string; label: string };
  stat: { value: string; label: string };
}) {
  const reduce = useReducedMotion();
  const [ready, setReady] = useState(false);
  useEffect(() => setReady(true), []);

  const fade = (delay: number) =>
    reduce
      ? {}
      : ready
        ? { initial: { opacity: 0, y: 16 }, animate: { opacity: 1, y: 0 }, transition: { duration: 0.6, delay, ease: "easeOut" as const } }
        : { initial: { opacity: 1 }, animate: { opacity: 1 } };

  return (
    <LazyMotion features={domAnimation}>
      <section id="hero" className="bg-background text-foreground">
        <div className="mx-auto grid max-w-page gap-10 px-gutter py-section lg:grid-cols-2 lg:items-center lg:gap-12">
          <div className="min-w-0">
            <m.p {...fade(0)} className="inline-flex items-center gap-2 rounded-control border border-border bg-card px-4 py-2 text-small text-card-foreground">
              <span aria-hidden="true" className="h-2 w-2 rounded-sm bg-primary" />
              {badge}
            </m.p>

            <m.h1 {...fade(0.1)} className="mt-6 font-display text-hero leading-tight text-foreground wrap-break-word">
