// Hero «layered»: a calm statement over a wide photo of a bright cabinet; on phones the text sits on a solid background above the photo.
import { srcSetOf } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";

export type HeroLayeredProps = {
  title: string;
  lead: string;
  note: string;
  image: { src: string; alt: string };
  wzId?: string;
};

export default function HeroLayered({ title, lead, note, image, wzId }: HeroLayeredProps) {
  const reduce = useReducedMotion();
  const enter = (step: number) =>
    reduce
      ? {}
      : {
          initial: { opacity: 0, y: 10 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.6, delay: step * 0.08, ease: [0.23, 1, 0.32, 1] as const },
        };
  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Hero" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <div className="relative overflow-hidden rounded-lg">
            <img
              src={image.src}
              srcSet={srcSetOf(image.src)}
              sizes="100vw"
              alt={image.alt}
              fetchPriority="high"
              className="aspect-3/2 w-full object-cover md:aspect-21/9"
            />
            <div className="bg-scrim text-scrim-foreground p-6 sm:p-10 md:p-12">
              <div className="max-w-text">
                <m.p {...enter(0)} className="text-small font-semibold tracking-wide uppercase">
                  {note}
                </m.p>
                <m.h1
                  {...enter(1)}
                  className="mt-3 font-display text-hero font-bold text-balance wrap-break-word"
                >
                  {title}
                </m.h1>
                <m.p {...enter(2)} className="mt-4 text-lead text-pretty">
                  {lead}
                </m.p>
                <m.a
                  {...enter(3)}
                  href="#form"
                  data-testid="wz-hero-primary"
                  className="mt-7 inline-flex min-h-11 items-center justify-center rounded-control bg-primary px-7 text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
                >
                  Оставить заявку
                </m.a>
              </div>
            </div>
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}

