        <div className="min-w-0 lg:col-span-7">
          <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
          <ol className="mt-8 border-t border-border">
            {items.map((item, i) => (
              <li key={item.title} className="flex gap-6 border-b border-border py-6">
                <span className="font-display text-h3 font-bold tabular-nums text-muted-foreground">
