}

// «How it works»: a vertical path of steps on the left, a photo of the reception on the right — different layout from the neighbours.
import { srcSetOf } from "@wizard/ui-kit/v3/headless";

export type StepsPathProps = {
  title: string;
  items: string[];
  note: string;
  image: { src: string; alt: string };
