// First screen «typographic»: a calm medical offer over a wide light photo, one h1, an eyebrow with the city and a single action; the entrance is a fade, only with the lively profile.
import { srcSetOf } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type Link = { label: string; href: string };
type Image = { src: string; alt: string };

export type HeroTypographicProps = {
  eyebrow: string;
  title: string;
  note?: string;
  action: Link;
  image: Image;
};

const primaryClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

export default function HeroTypographic({ eyebrow, title, note, action, image }: HeroTypographicProps) {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const fade = (step: number) =>
    lively && !reduce
      ? { initial: { opacity: 0, y: 10 }, animate: { opacity: 1, y: 0 }, transition: { duration: 0.5, delay: step * 0.08 } }
      : {};
  return (
    <LazyMotion features={domAnimation}>
      <section id="hero" className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page items-end gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-14">
          <div className="min-w-0 lg:col-span-7">
            <p className="text-small font-bold tracking-wide text-muted-foreground uppercase">{eyebrow}</p>
            <m.h1
              {...fade(0)}
              className="mt-4 font-display text-hero font-bold text-balance wrap-break-word hyphens-auto"
            >
              {title}
            </m.h1>
            {note ? <m.p {...fade(1)} className="mt-5 max-w-text text-lead text-muted-foreground">{note}</m.p> : null}
            <m.div {...fade(2)} className="mt-8">
              <a href={action.href} data-testid="wz-hero-primary" className={primaryClass}>
                {action.label}
              </a>
            </m.div>
          </div>
          <m.div {...fade(1)} className="min-w-0 lg:col-span-5">
            <img
              src={image.src}
              srcSet={srcSetOf(image.src)}
              sizes="(min-width: 1024px) 40vw, 100vw"
              alt={image.alt}
              fetchPriority="high"
              className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
            />
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

// Contacts: address and phone on the left, a photo of the reception hall on the right — a calm, air section after the dense catalog; a phone link and the street address from the facts.
type Image = { src: string; alt: string };

export type ContactsProps = {
  title: string;
  phone: string;
  phoneHref: string;
  address: string;
  items: { text: string }[];
};

const linkClass =
  "font-display text-h3 font-bold text-foreground underline decoration-primary decoration-2 underline-offset-4 transition-colors duration-200 hover:decoration-foreground";

export default function Contacts({ title, phone, phoneHref, address, items }: ContactsProps) {
  return (
    <section id="contacts" className="bg-card font-sans text-card-foreground">
      <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-2 lg:gap-14">
        <div className="min-w-0">
          <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
          <a href={phoneHref} className={`mt-6 inline-block wrap-break-word ${linkClass}`}>
            {phone}
          </a>
          <p className="mt-3 text-body text-muted-foreground">{address}</p>
          {items.length > 0 ? (
            <ul className="mt-6 space-y-2 border-t border-border pt-6">
              {items.map((i) => (
                <li key={i.text} className="text-body text-muted-foreground">
                  {i.text}
                </li>
              ))}
            </ul>
          ) : null}
        </div>
