  return (
    <LazyMotion features={domAnimation}>
      <section id="cta" className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <m.div {...fade} className="flex flex-col gap-6 rounded-lg border border-border bg-card p-8 text-card-foreground md:p-12">
