// First screen «split»: the offer on the left (title, lead, one action, one practical line), a photo on the right;
// on phones the text comes first and the photo follows. Calm medical composition on the design system tokens.
import { srcSetOf, useFitWords } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type Link = { label: string; href: string };
type Image = { src: string; alt: string };

export type HeroSplitProps = {
  title: string;
  lead?: string;
  action: Link;
  note?: string;
  image: Image;
  wzId?: string;
};

const primaryClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

/** Entrance of the first screen: once, only with the lively motion profile, never with reduced motion. */
function useEnter() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return (step: number) =>
    on
      ? {
          initial: { opacity: 0, y: 12 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.6, delay: step * 0.05, ease: [0.23, 1, 0.32, 1] as const },
        }
      : {};
}

export default function HeroSplit({ title, lead, action, note, image, wzId }: HeroSplitProps) {
  const enter = useEnter();
  const fit = useFitWords<HTMLHeadingElement>(title);
  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Hero" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-14">
          <div className="min-w-0 lg:col-span-6">
            <m.h1
              ref={fit}
              {...enter(0)}
              className="font-display text-hero font-bold text-balance wrap-break-word hyphens-auto"
            >
              {title}
            </m.h1>
            {lead ? (
              <m.p {...enter(1)} className="mt-5 max-w-text text-lead text-pretty text-muted-foreground">
                {lead}
              </m.p>
            ) : null}
            <m.div {...enter(2)} className="mt-8">
              <a href={action.href} data-testid="wz-hero-primary" className={primaryClass}>
                {action.label}
              </a>
            </m.div>
            {note ? <p className="mt-5 text-small text-muted-foreground">{note}</p> : null}
          </div>
          <m.div {...enter(1)} className="min-w-0 lg:col-span-6">
            <img
              src={image.src}
              srcSet={srcSetOf(image.src)}
              sizes="(min-width: 1024px) 50vw, 100vw"
              alt={image.alt}
              fetchPriority="high"
              className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
            />
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

// «How it works»: three steps as a ruled list beside a photo of the doctor at work; calm rhythm, tabular order.
type Image = { src: string; alt: string };
type Step = { title: string; text: string };

export type StepsProps = {
  title: string;
  intro?: string;
  items: Step[];
  image: Image;
  wzId?: string;
};

export default function Steps({ title, intro, items, image, wzId }: StepsProps) {
  return (
    <section className="bg-card font-sans text-card-foreground">
      <div className="mx-auto grid w-full max-w-page items-start gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-14">
        <div className="min-w-0 lg:col-span-5">
          <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
          {intro ? (
            <p className="mt-4 max-w-text text-lead text-pretty text-muted-foreground">{intro}</p>
          ) : null}
          <img
            src={image.src}
            srcSet={srcSetOf(image.src)}
            sizes="(min-width: 1024px) 40vw, 100vw"
            alt={image.alt}
            loading="lazy"
            className="mt-8 aspect-3/2 w-full rounded-lg bg-muted object-cover"
          />
        </div>
        <ol className="min-w-0 lg:col-span-7 lg:pt-4">
          {items.map((s, i) => (
            <li key={s.title} className="border-t border-border py-7 first:border-t-2 first:border-t-foreground">
              <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{s.title}</h3>
              <p className="mt-2 max-w-text text-body text-pretty text-muted-foreground">{s.text}</p>
            </li>
          ))}
        </ol>
      </div>
    </section>
  );
}

import { srcSetOf } from "@wizard/ui-kit/v3/headless";

// FAQ and contacts side by side: a question with an honest answer on the left, phone and address on the right.
export type FaqContactsProps = {
  title: string;
  faq: { question: string; answer: string }[];
  phone: string;
  address: string;
  wzId?: string;
};

const phoneClass =
  "font-display text-h2 font-bold text-foreground underline decoration-primary decoration-2 underline-offset-4 transition-colors duration-200 hover:decoration-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

export default function FaqContacts({ title, faq, phone, address, wzId }: FaqContactsProps) {
  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto grid w-full max-w-page gap-12 px-gutter py-section lg:grid-cols-12 lg:gap-14">
        <div className="min-w-0 lg:col-span-7">
          <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
          <ul className="mt-8">
            {faq.map((f) => (
              <li key={f.question} className="border-t border-border py-7">
                <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{f.question}</h3>
                <p className="mt-3 max-w-text text-body text-pretty text-muted-foreground">{f.answer}</p>
              </li>
            ))}
          </ul>
        </div>
        <div className="min-w-0 lg:col-span-5 lg:pt-16">
          <div className="rounded-lg bg-card p-8 text-card-foreground">
            <h3 className="font-display text-h3 font-bold">Клиника «Белая линия»</h3>
            <a href={`tel:${phone.replace(/[^+\d]/g, "")}`} className={`mt-4 inline-block wrap-break-word ${phoneClass}`}>
              {phone}
            </a>
            <p className="mt-4 text-body text-muted-foreground wrap-break-word">{address}</p>
            <p className="mt-4 text-small text-muted-foreground">Приходите или позвоните — администратор ответит и подберёт время приёма.</p>
          </div>
        </div>
      </div>
    </section>
  );
}

// CTA band: a calm inverse band with the question, one action and the front-desk photo as a wide strip below.
import { srcSetOf } from "@wizard/ui-kit/v3/headless";

type Link = { label: string; href: string };
type Image = { src: string; alt: string };

export type CtaBandProps = {
  title: string;
  action: Link;
  note?: string;
  image: Image;
  wzId?: string;
};

const inverseClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-inverse px-6 text-center text-body font-bold text-inverse-foreground transition-colors duration-200 hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

export default function CtaBand({ title, action, note, image, wzId }: CtaBandProps) {
  return (
    <section className="bg-scrim font-sans text-scrim-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="flex flex-col gap-6 lg:flex-row lg:items-center lg:justify-between">
          <div className="min-w-0">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
            {note ? <p className="mt-3 max-w-text text-body text-pretty text-scrim-foreground/80">{note}</p> : null}
          </div>
          <a href={action.href} data-testid="wz-cta-action" className={inverseClass}>
            {action.label}
          </a>
        </div>
        <img
          src={image.src}
          srcSet={srcSetOf(image.src)}
          sizes="100vw"
          alt={image.alt}
          loading="lazy"
          className="mt-10 aspect-3/2 w-full rounded-lg bg-muted object-cover"
        />
      </div>
    </section>
  );
}

