// Steps «how recording goes»: three steps laid out horizontally with large display typography —
// the step number drawn by code (not by content), a thin rule above each step, title and text below.
// After the steps: a full-width photo of a doctor with a scan on screen, 3:2, with a short caption
// to break the dense rhythm. Own composition; all texts and the photo come from props.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";
import { srcSetOf, IMAGE_WIDTHS, safeHref } from "@wizard/ui-kit/v3/headless";

type Step = { title: string; text: string };
type Photo = { src: string; alt: string };

export type StepsProps = {
  title: string;
  items: Step[];
  photo: Photo;
};

const easeCalm = [0.25, 0.4, 0.25, 1] as const;

export default function Steps({ title, items, photo }: StepsProps) {
  const reduced = useReducedMotion();

  const stepVariants = {
    hidden: { opacity: 0, y: reduced ? 0 : 16 },
    visible: (i: number) => ({
      opacity: 1,
      y: 0,
      transition: { duration: reduced ? 0 : 0.5, ease: easeCalm, delay: reduced ? 0 : 0.12 * i },
    }),
  };

  return (
    <LazyMotion features={domAnimation} strict>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <h2 className="max-w-text font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>

          <ol className="mt-12 grid gap-x-8 gap-y-10 border-t-2 border-foreground md:grid-cols-3 md:gap-y-0">
            {items.map((step, i) => (
              <m.li
                key={step.title}
                custom={i}
                variants={stepVariants}
                initial="hidden"
                whileInView="visible"
                viewport={{ once: true, amount: 0.4 }}
                className="min-w-0 border-border pt-6 md:pt-8 md:not-last:border-r md:not-last:border-b-0 [&:not(:last-child)]:border-b md:[&:not(:last-child)]:border-b-0"
              >
                <p
                  aria-hidden="true"
                  className="font-display text-h1 font-bold leading-none text-muted-foreground/40 tabular-nums select-none"
                >
                  {String(i + 1).padStart(2, "0")}
                </p>
                <h3 className="mt-4 font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                <p className="mt-2 max-w-text text-body text-pretty text-muted-foreground wrap-break-word">
                  {step.text}
                </p>
              </m.li>
            ))}
          </ol>

          <m.figure
            initial={{ opacity: reduced ? 1 : 0 }}
            whileInView={{ opacity: 1 }}
            viewport={{ once: true, amount: 0.25 }}
            transition={{ duration: reduced ? 0 : 0.6, ease: easeCalm }}
            className="mt-12"
          >
            <img
              src={safeHref(photo.src) ?? photo.src}
              srcSet={srcSetOf(photo.src, IMAGE_WIDTHS)}
              sizes="(min-width: 1440px) 1440px, 100vw"
              alt={photo.alt}
              loading="lazy"
              className="aspect-3/2 w-full rounded-lg object-cover"
            />
            <figcaption className="mt-4 max-w-text text-small text-muted-foreground">{photo.alt}</figcaption>
          </m.figure>
        </div>
      </section>
    </LazyMotion>
  );
}

