// First screen «split»: calm medical offer on the left (hero title with a primary accent on «без боли»,
// a lead line and one action to the form), a bright cabinet photo in a rounded 3:2 frame on the right;
// on phones the title and button come first, the photo follows.
import { srcSetOf, useFitWords } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type Link = { label: string; href: string };
type Image = { src: string; alt: string };

export type HeroProps = {
  title: string;
  subtitle?: string;
  button: Link;
  photo: Image;
  /** Place of the section in the page source: the build injects it (ui-kit.yaml#wz_id), never the composer. */
  wzId?: string;
};

/** Calm entrance (fade, no travel) — only with the lively motion profile and never with reduced motion. */
function useEnter() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return (step: number) =>
    on
      ? {
          initial: { opacity: 0 },
          animate: { opacity: 1 },
          transition: { duration: 0.7, delay: step * 0.1, ease: "easeOut" as const },
        }
      : {};
}

/** Splits the title so the phrase «без боли» gets the accent color; falls back to plain text. */
function accentTitle(title: string) {
  const phrase = "без боли";
  const i = title.indexOf(phrase);
  if (i === -1) return [{ text: title, accent: false }];
  return [
    { text: title.slice(0, i), accent: false },
    { text: phrase, accent: true },
    { text: title.slice(i + phrase.length), accent: false },
  ];
}

const buttonClass =
  "inline-flex min-h-11 items-center justify-center rounded-control bg-primary px-7 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

export default function Hero({ title, subtitle, button, photo, wzId }: HeroProps) {
  const enter = useEnter();
  const fit = useFitWords<HTMLHeadingElement>(title);
  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Hero" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-14">
          <div className="order-1 min-w-0 lg:col-span-6">
            <m.h1
              ref={fit}
              {...enter(0)}
              className="font-display text-hero font-bold text-balance wrap-break-word hyphens-auto"
            >
              {accentTitle(title).map((part, i) =>
                part.accent ? (
                  <span key={i} className="text-primary">
                    {part.text}
                  </span>
                ) : (
                  <span key={i}>{part.text}</span>
                ),
              )}
            </m.h1>
            <m.div {...enter(1)} className="mt-7">
              <a href={button.href} data-testid="wz-hero-primary" className={buttonClass}>
                {button.label}
              </a>
            </m.div>
            {subtitle ? (
              <m.p {...enter(2)} className="mt-5 max-w-text text-lead text-muted-foreground">
                {subtitle}
              </m.p>
            ) : null}
          </div>
          <m.div {...enter(1)} className="order-2 min-w-0 lg:col-span-6">
            <img
              src={photo.src}
              srcSet={srcSetOf(photo.src)}
              sizes="(min-width: 1024px) 50vw, 100vw"
              alt={photo.alt}
              fetchPriority="high"
              className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
            />
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

