// Hero (first screen), «split»: the offer on the left — one headline, one lead line, one action;
// the photo of a light clinic room on the right, framed rounded 3:2. On phones: title, line, button, then photo.
// No second action, no notes. Calm entrance (fade), calm hover tint; still without motion.
import { srcSetOf, useFitWords } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

export type HeroProps = {
  title: string;
  subtitle: string;
  cta: string;
  ctaHref: string;
  photo: string;
  photoAlt: string;
  /** Place of the section in the page source: the build injects it (ui-kit.yaml#wz_id), never the composer. */
  wzId?: string;
};

const ctaClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-7 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

/** Calm entrance (fade, catalog E3): once, only with the lively motion profile, never with reduced motion. */
function useEnter() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return (step: number) =>
    on
      ? {
          initial: { opacity: 0, y: 10 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.5, delay: step * 0.08, ease: [0.23, 1, 0.32, 1] as const },
        }
      : {};
}

export default function Hero({ title, subtitle, cta, ctaHref, photo, photoAlt, wzId }: HeroProps) {
  const enter = useEnter();
  const fit = useFitWords<HTMLHeadingElement>(title);
  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Hero" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-14">
          <div className="order-1 min-w-0 lg:col-span-6">
            <m.h1
              ref={fit}
              {...enter(0)}
              className="font-display text-hero font-bold text-balance wrap-break-word hyphens-auto"
            >
              {title}
            </m.h1>
            {subtitle ? (
              <m.p {...enter(1)} className="mt-5 max-w-text text-lead text-muted-foreground">
                {subtitle}
              </m.p>
            ) : null}
            <m.div {...enter(2)} className="mt-8">
              <a href={ctaHref} data-testid="wz-hero-primary" className={ctaClass}>
                {cta}
              </a>
            </m.div>
          </div>
          <m.div {...enter(1)} className="order-2 min-w-0 lg:col-span-6">
            <img
              src={photo}
              srcSet={srcSetOf(photo)}
              sizes="(min-width: 1024px) 50vw, 100vw"
              alt={photoAlt}
              fetchPriority="high"
              className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
            />
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

