args.source:
// Steps «how booking works»: airy section after the dense catalog — the steps as a vertical ledger,
// not tiles: each step is a row with an oversized code-drawn numeral on the left and generous
// display-sized text on the right, separated by calm rules; the last row carries the link
// to the application form. One column reads as a sequence, not a card grid.
type Step = { text: string };

export type BookingStepsProps = {
  title: string;
  items: Step[];
  ctaLabel: string;
  ctaHref: string;
};

import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

const stepLinkClass =
  "inline-flex min-h-11 items-center text-body font-bold text-primary underline decoration-primary decoration-2 underline-offset-4 transition-colors duration-200 hover:text-foreground hover:decoration-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

export default function BookingSteps({ title, items, ctaLabel, ctaHref }: BookingStepsProps) {
  const still = useReducedMotion();

  const fade = (delay = 0) =>
    still
      ? {}
      : {
          initial: { opacity: 0, y: 16 },
          whileInView: { opacity: 1, y: 0 },
          viewport: { once: true, amount: 0.3 },
          transition: { duration: 0.5, ease: "easeOut" as const, delay },
        };

  return (
    <LazyMotion features={domAnimation} strict>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <m.h2 {...fade()} className="max-w-text font-display text-h1 font-bold text-balance wrap-break-word">
            {title}
          </m.h2>

          <ol className="mt-12 md:mt-16">
            {items.map((step, i) => {
              const isLast = i === items.length - 1;
              return (
                <m.li
                  key={step.text}
                  {...fade(i * 0.08)}
                  className="grid grid-cols-[auto_1fr] items-baseline gap-x-6 gap-y-4 border-t border-border py-8 sm:gap-x-10 md:py-10"
                >
                  {/* numeral drawn by code: oversized, muted, tabular so rows align */}
                  <span
                    aria-hidden="true"
                    className="min-w-10 font-display text-h1 font-bold leading-none tabular-nums text-muted-foreground"
                  >
                    {i + 1}
                  </span>
                  <div className="min-w-0 md:flex md:items-baseline md:justify-between md:gap-12">
                    <p className="max-w-text font-display text-h2 font-bold text-pretty wrap-break-word text-foreground">
                      {step.text}
                    </p>
                    {isLast ? (
                      <a href={ctaHref} className={`mt-2 shrink-0 md:mt-0 ${stepLinkClass}`}>
                        {ctaLabel}
                      </a>
                    ) : null}
                  </div>
                </m.li>
              );
            })}
          </ol>
        </div>
      </section>
    </LazyMotion>
  );
}

