// Cta: a short final call — one large question and one verb-button to the form, nothing else (calm, split rhythm).
export type CtaProps = {
  title: string;
  cta: string;
  ctaAnchor: string;
};

export default function Cta({ title, cta, ctaAnchor }: CtaProps) {
  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="flex flex-col items-start gap-8 border-t-2 border-border md:flex-row md:items-baseline md:justify-between md:gap-12">
          <h2 className="min-w-0 font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
          <a
            href={ctaAnchor}
            className="inline-flex min-h-11 items-center justify-center rounded-control bg-primary px-8 py-3 text-lead font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
          >
            {cta}
          </a>
        </div>
      </div>
    </section>
  );
}

