// Hall: the visual finale of the page — one large photo of the clinic hall on a calm
// background, with a short invitation caption beside it. Photo in 3:2, rounded frame.
import { srcSetOf, IMAGE_WIDTHS } from "@wizard/ui-kit/v3/headless";

export type HallProps = {
  title: string;
  text: string;
  photo: string;
  alt: string;
};

export default function Hall({ title, text, photo, alt }: HallProps) {
  return (
    <section className="bg-muted font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid items-end gap-x-10 gap-y-6 lg:grid-cols-12">
          <figure className="min-w-0 lg:col-span-8">
            <img
              src={photo}
              srcSet={srcSetOf(photo, IMAGE_WIDTHS)}
              sizes="(min-width: 1024px) 66vw, 100vw"
              alt={alt}
              loading="lazy"
              className="aspect-3/2 w-full rounded-lg object-cover"
            />
          </figure>
          <div className="min-w-0 lg:col-span-4">
            <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
            <p className="mt-4 max-w-text text-lead text-pretty text-muted-foreground">{text}</p>
          </div>
        </div>
      </div>
    </section>
  );
