// Steps «how the visit is booked»: an airy section — the h2 title above, then three steps on one line,
// each step's number drawn as code (tabular figures, shrink-0) on the same baseline as the step's title
// (T17 numbering rule); a quiet signal-accented arrow at the end links the row to the booking form.
// On the phone the steps stack into a vertical column with a rule instead of the arrow.
type StepsProps = {
  title: string;
  items: string[];
  formHref?: string;
};

export default function StepsHowToBook({ title, items, formHref = "#form" }: StepsProps) {
  const safeHref = formHref.startsWith("#") ? formHref : "#form";
  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <h2 className="max-w-text font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>

        <ol className="mt-14 grid items-start gap-10 md:mt-20 md:grid-cols-[1fr_auto_1fr_auto_1fr_auto] md:gap-8">
          {items.map((label, i) => (
            <li key={label} className="flex min-w-0 flex-col">
              <div className="flex items-baseline gap-3">
                <span
                  aria-hidden="true"
                  className="shrink-0 font-display text-h2 font-bold tabular-nums text-primary"
                >
                  {String(i + 1)}
                </span>
                <h3 className="min-w-0 font-display text-h3 font-bold text-balance wrap-break-word">{label}</h3>
              </div>
              <span
                aria-hidden="true"
                className="mt-6 hidden h-px w-full border-t border-border md:block"
              />
              {i < items.length - 1 ? (
                <span
                  aria-hidden="true"
                  className="mt-6 text-h2 leading-none text-primary md:hidden"
                >
                  ↓
                </span>
              ) : null}
            </li>
          ))}

          <li className="hidden items-center md:col-start-auto md:flex">
            <a
              href={safeHref}
              aria-label="Перейти к форме записи"
              className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control px-4 font-display text-h2 leading-none text-primary transition-colors duration-200 hover:bg-primary hover:text-primary-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
            >
              →
            </a>
          </li>
        </ol>
      </div>
    </section>
  );
}

