// FAQ: a large heading above a calm accordion — native disclosure pattern with heavy rules
// between questions, answers address the patient's fears before treatment (catalog D2, T17).
import { useState } from "react";
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type Item = {
  question: string;
  answer: string;
};

export type FaqProps = {
  title: string;
  items: Item[];
};

export default function Faq({ title, items }: FaqProps) {
  const [open, setOpen] = useState<number>(-1);
  const reduce = useReducedMotion();

  return (
    <LazyMotion features={domAnimation} strict>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <div className="grid gap-10 md:grid-cols-12">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word md:col-span-5">
              {title}
            </h2>
            <ul className="min-w-0 border-t-2 border-foreground md:col-span-7">
              {items.map((item, i) => {
                const isOpen = open === i;
                return (
                  <li key={item.question} className="border-b border-border">
                    <button
                      type="button"
                      aria-expanded={isOpen}
                      onClick={() => setOpen(isOpen ? -1 : i)}
                      className="flex min-h-11 w-full items-baseline justify-between gap-6 py-6 text-left focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
                    >
                      <span className="font-display text-h3 font-bold text-balance wrap-break-word">
                        {item.question}
                      </span>
                      <span
                        aria-hidden="true"
                        className="shrink-0 font-display text-h3 font-bold text-primary transition-transform duration-200"
                        style={{ transform: isOpen ? "rotate(45deg)" : "none" }}
                      >
                        +
                      </span>
                    </button>
                    <m.div
                      initial={false}
                      animate={
                        reduce || isOpen
                          ? { height: isOpen ? "auto" : 0, opacity: isOpen ? 1 : 0 }
                          : { height: isOpen ? "auto" : 0, opacity: isOpen ? 1 : 0 }
                      }
                      transition={reduce ? { duration: 0 } : { duration: 0.25, ease: "easeOut" }}
                      className="overflow-hidden"
                    >
                      <p className="max-w-text pb-6 text-lead text-pretty text-muted-foreground">
                        {item.answer}
                      </p>
                    </m.div>
                  </li>
                );
              })}
            </ul>
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}

