// Contacts: final airy section — huge phone number as the hero element with a tel: link,
// address and a call-to-action beneath it; large clickable number on mobile. Calm fade-in only.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

export type ContactsProps = {
  title: string;
  phone: string;
  address: string;
  cta: { label: string; href: string };
};

const telHref = (phone: string) => "tel:" + phone.replace(/[^+\d]/g, "");

export default function Contacts({ title, phone, address, cta }: ContactsProps) {
  const reduced = useReducedMotion();
  const fade = reduced || true ? {} : { initial: { opacity: 0 }, whileInView: { opacity: 1 }, viewport: { once: true, amount: 0.3 }, transition: { duration: 0.5 } };

  return (
    <LazyMotion features={domAnimation} strict>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <m.div {...fade}>
            <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>

            <a
              href={telHref(phone)}
              className="mt-6 block font-display text-hero font-bold tracking-tight text-primary wrap-break-word transition-colors duration-200 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring"
            >
              {phone}
            </a>

            <p className="mt-6 max-w-text text-lead text-muted-foreground text-pretty">{address}</p>

            <a
              href={cta.href}
              className="mt-10 inline-flex min-h-11 items-center justify-center rounded-control bg-primary px-8 text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
            >
              {cta.label}
            </a>
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

