// FAQ: airy full-width section — large title on the left, expanding question rows on the right.
// Answer reveals on click via m.* height animation, calm fade profile; first item open by default.
import { useState } from "react";
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type Item = { question: string; answer: string };

export type FaqProps = {
  title: string;
  items: Item[];
};

const triggerClass =
  "flex min-h-11 w-full items-baseline justify-between gap-6 py-6 text-left transition-colors duration-200 hover:text-primary focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

export default function Faq({ title, items }: FaqProps) {
  const [open, setOpen] = useState<number | null>(items.length > 0 ? 0 : null);
  const reduced = useReducedMotion();

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-x-12 gap-y-10 md:grid-cols-12 md:gap-y-0">
          <div className="md:col-span-4">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word md:sticky md:top-8 md:self-start">
              {title}
            </h2>
          </div>
          <div className="min-w-0 md:col-span-8">
            <ul className="border-t-2 border-foreground">
              {items.map((item, i) => {
                const isOpen = open === i;
                const panelId = `faq-panel-${i}`;
                return (
                  <li key={item.question} className="border-b border-border">
                    <button
                      type="button"
                      aria-expanded={isOpen}
                      aria-controls={panelId}
                      onClick={() => setOpen(isOpen ? null : i)}
                      className={triggerClass}
                    >
                      <span className="min-w-0 font-display text-h3 font-bold text-balance wrap-break-word">
                        {item.question}
                      </span>
                      <span
                        aria-hidden="true"
                        className={`shrink-0 font-display text-h3 font-bold leading-none transition-colors duration-200 ${
                          isOpen ? "text-primary" : "text-muted-foreground"
                        }`}
                      >
                        {isOpen ? "–" : "+"}
                      </span>
                    </button>
                    <m.div
                      id={panelId}
                      role="region"
                      initial={false}
                      animate={{
                        height: isOpen ? "auto" : 0,
                        opacity: isOpen ? 1 : 0,
                      }}
                      transition={
                        reduced
                          ? { duration: 0 }
                          : { duration: 0.35, ease: [0.22, 1, 0.36, 1] }
                      }
                      className="overflow-hidden"
                      style={{ height: isOpen ? "auto" : 0, opacity: isOpen ? 1 : 0 }}
                    >
                      <p className="max-w-text pb-7 text-lead text-pretty text-muted-foreground">
                        {item.answer}
                      </p>
                    </m.div>
                  </li>
                );
              })}
            </ul>
          </div>
        </div>
      </div>
    </section>
  );
}

