// Steps «how booking works»: a photo of the reception desk anchored on the left, and the three steps
// laid out as a horizontal sequence on the right — the step number is drawn by the code, sitting on the
// same baseline as the step title; photo keeps a 3:2 frame (aspect-[3/2], rounded). Calm motion: fade-in.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";
import { srcSetOf, IMAGE_WIDTHS } from "@wizard/ui-kit/v3/headless";

type Image = { src: string; alt: string };

export type StepsProps = {
  title: string;
  steps: string[];
  photo?: Image;
};

export default function StepsSection({ title, steps, photo }: StepsProps) {
  const reduce = useReducedMotion();

  return (
    <section className="bg-background font-sans text-foreground">
      <LazyMotion features={domAnimation} strict>
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <div className="grid items-center gap-x-10 gap-y-10 lg:grid-cols-12">
            {photo ? (
              <m.figure
                initial={reduce ? false : { opacity: 0, y: 16 }}
                whileInView={reduce ? undefined : { opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.3 }}
                transition={{ duration: 0.6, ease: "easeOut" }}
                className="min-w-0 lg:col-span-5"
              >
                <img
                  src={photo.src}
                  srcSet={srcSetOf(photo.src, IMAGE_WIDTHS)}
                  sizes="(min-width: 1024px) 40vw, 100vw"
                  alt={photo.alt}
                  className="aspect-3/2 w-full rounded-lg object-cover"
                />
              </m.figure>
            ) : null}

            <div className={`min-w-0 ${photo ? "lg:col-span-7" : "lg:col-span-12"}`}>
              <m.h2
                initial={reduce ? false : { opacity: 0, y: 16 }}
                whileInView={reduce ? undefined : { opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.5 }}
                transition={{ duration: 0.6, ease: "easeOut" }}
                className="font-display text-h1 font-bold text-balance wrap-break-word"
              >
                {title}
              </m.h2>

              <ol className="mt-10 grid gap-y-8 sm:grid-cols-3 sm:gap-x-8 lg:mt-12">
                {steps.map((step, i) => (
                  <m.li
                    key={step}
                    initial={reduce ? false : { opacity: 0, y: 16 }}
                    whileInView={reduce ? undefined : { opacity: 1, y: 0 }}
                    viewport={{ once: true, amount: 0.5 }}
                    transition={{ duration: 0.6, ease: "easeOut", delay: reduce ? 0 : i * 0.12 }}
                    className="min-w-0"
