// Form section — dense appointment block: title and intro left, request form right,
// and a large 3:2 photo of the doctor with a patient to support trust (D2 split grid, T11).
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

export type FormSectionProps = {
  title: string;
  intro: string;
  photo: { src: string; alt: string };
  submit_label: string;
};

const inputClass =
  "min-h-11 w-full rounded-control border border-border bg-card px-4 py-3 text-body text-foreground placeholder:text-muted-foreground focus:border-primary focus:outline-2 focus:outline-offset-2 focus:outline-ring";

export default function FormSection({ title, intro, photo, submit_label }: FormSectionProps) {
  const reduce = useReducedMotion();

  return (
    <LazyMotion features={domAnimation} strict>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <div className="grid gap-x-12 gap-y-10 lg:grid-cols-12 lg:items-start">
            <m.div
              initial={reduce ? false : { opacity: 0, y: 16 }}
              whileInView={reduce ? undefined : { opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-80px" }}
              transition={{ duration: 0.5, ease: "easeOut" }}
              className="min-w-0 lg:col-span-5"
            >
              <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
              <p className="mt-4 max-w-text text-lead text-pretty text-muted-foreground">{intro}</p>
            </m.div>

            <m.form
              initial={reduce ? false : { opacity: 0, y: 16 }}
              whileInView={reduce ? undefined : { opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-80px" }}
              transition={{ duration: 0.5, delay: 0.1, ease: "easeOut" }}
              className="min-w-0 lg:col-span-7"
            >
              <div className="rounded-lg border border-border bg-card p-6 text-card-foreground sm:p-8">
                <div className="grid gap-5 sm:grid-cols-2">
                  <label className="block min-w-0">
                    <span className="sr-only">Имя</span>
                    <input type="text" name="name" autoComplete="name" required aria-label="Имя" className={inputClass} />
                  </label>
                  <label className="block min-w-0">
                    <span className="sr-only">Телефон</span>
                    <input
                      type="tel"
                      name="phone"
                      autoComplete="tel"
                      required
                      aria-label="Телефон"
                      className={inputClass}
                    />
                  </label>
                </div>
                <label className="mt-5 block min-w-0">
                  <span className="sr-only">Комментарий</span>
                  <textarea
                    name="comment"
                    rows={4}
                    aria-label="Комментарий"
                    className={`${inputClass} resize-none`}
                  />
                </label>
                <button
                  type="submit"
                  className="mt-6 inline-flex min-h-11 w-full items-center justify-center rounded-control bg-primary px-8 text-center text-lead font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring sm:w-auto"
                >
                  {submit_label}
                </button>
              </div>
            </m.form>
          </div>

          <m.figure
            initial={reduce ? false : { opacity: 0 }}
            whileInView={reduce ? undefined : { opacity: 1 }}
            viewport={{ once: true, margin: "-80px" }}
            transition={{ duration: 0.6, ease: "easeOut" }}
            className="mt-12 min-w-0"
          >
            <img
              src={photo.src}
              alt={photo.alt}
              loading="lazy"
              className="aspect-3/2 w-full rounded-lg object-cover"
            />
          </m.figure>
        </div>
      </section>
    </LazyMotion>
  );
}

