args.source:
// Steps «how booking works»: a photo of the reception desk anchored on the left, and the three steps
// as a vertical price-list-style sequence of rows on the right — the step number is drawn by the code,
// sitting on the same baseline as the step title, each row separated by a rule. Calm motion: fade-in.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";
import { srcSetOf } from "@wizard/ui-kit/v3/headless";

type Image = { src: string; alt: string };

export type StepsProps = {
  title: string;
  steps: string[];
  photo?: Image;
};

export default function StepsSection({ title, steps, photo }: StepsProps) {
  const reduce = useReducedMotion();
  const fade = (delay = 0) =>
    reduce
      ? {}
      : {
          initial: { opacity: 0, y: 16 },
          whileInView: { opacity: 1, y: 0 },
          viewport: { once: true, amount: 0.4 },
          transition: { duration: 0.6, ease: "easeOut" as const, delay },
        };

  return (
    <section className="bg-background font-sans text-foreground">
      <LazyMotion features={domAnimation} strict>
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <div className="grid items-start gap-x-12 gap-y-10 lg:grid-cols-12">
            {photo ? (
              <m.figure {...fade()} className="min-w-0 lg:col-span-5">
                <img
                  src={photo.src}
                  srcSet={srcSetOf(photo.src)}
                  sizes="(min-width: 1024px) 40vw, 100vw"
                  alt={photo.alt}
                  className="aspect-3/2 w-full rounded-lg object-cover"
                />
              </m.figure>
            ) : null}

            <div className={`min-w-0 ${photo ? "lg:col-span-7" : "lg:col-span-12"}`}>
              <m.h2
                {...fade()}
                className="font-display text-h1 font-bold text-balance wrap-break-word"
              >
                {title}
              </m.h2>

              <ol className="mt-8 border-t-2 border-foreground lg:mt-10">
                {steps.map((step, i) => (
                  <m.li
                    key={step}
                    {...fade(reduce ? 0 : i * 0.1)}
                    className="flex items-baseline gap-4 border-b border-border py-6 sm:gap-6 sm:py-7"
                  >
                    <span
                      aria-hidden="true"
                      className="shrink-0 font-display text-h2 font-bold leading-none text-primary tabular-nums"
                    >
                      {i + 1}
                    </span>
                    <h3 className="min-w-0 font-display text-h3 font-bold text-balance wrap-break-word">
                      {step}
                    </h3>
                  </m.li>
                ))}
              </ol>
            </div>
          </div>
        </div>
      </LazyMotion>
    </section>
  );
}

