// FAQ: a calm closing section — the title, then a single open question answered inline under a rule;
// no hidden accordion mechanics: the fear question gets a direct, visible answer (F8 Single QA).
type Item = { question: string; answer: string };

export type FaqProps = {
  title: string;
  items: Item[];
};

export default function Faq({ title, items }: FaqProps) {
  return (
    <section className="bg-muted font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-x-12 gap-y-8 md:grid-cols-12">
          <div className="min-w-0 md:col-span-4">
            <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
          </div>
          <div className="min-w-0 md:col-span-8">
            <ul className="border-t-2 border-foreground">
              {items.map((item) => (
                <li key={item.question} className="border-b border-border py-8">
                  <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{item.question}</h3>
                  <p className="mt-4 max-w-text text-lead text-pretty text-muted-foreground">{item.answer}</p>
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>
    </section>
  );
}

