// Hero «split»: a large offer headline on the left over a light background, a 3:2 photo of the office
// on the right inside a rounded frame; on phones the title and button come first, then the photo.
import { srcSetOf, useFitWords } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

export type HeroProps = {
  title: string;
  subtitle?: string;
  cta: { label: string; href: string };
  photo: { src: string; alt: string };
  wzId?: string;
};

/** Calm motion: a single fade-in on load, only with the lively profile and never with reduced motion. */
function useEnter() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return (step: number) =>
    on
      ? {
          initial: { opacity: 0, y: 10 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.5, delay: step * 0.08, ease: [0.23, 1, 0.32, 1] as const },
        }
      : {};
}

const ctaClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-8 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

export default function Hero({ title, subtitle, cta, photo, wzId }: HeroProps) {
  const enter = useEnter();
  const fit = useFitWords<HTMLHeadingElement>(title);
  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Hero" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-16">
          <div className="order-1 min-w-0 lg:col-span-6">
            <m.h1
              ref={fit}
              {...enter(0)}
              className="font-display text-hero font-bold text-balance wrap-break-word hyphens-auto"
            >
              {title}
            </m.h1>
            {subtitle ? (
              <m.p {...enter(1)} className="mt-6 max-w-text text-lead text-muted-foreground">
                {subtitle}
              </m.p>
            ) : null}
            <m.div {...enter(2)} className="mt-9">
              <a href={cta.href} data-testid="wz-hero-primary" className={ctaClass}>
                {cta.label}
              </a>
            </m.div>
          </div>
          <m.div {...enter(1)} className="order-2 min-w-0 lg:col-span-6">
            <img
              src={photo.src}
              srcSet={srcSetOf(photo.src)}
              sizes="(min-width: 1024px) 50vw, 100vw"
              alt={photo.alt}
              fetchPriority="high"
              className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
            />
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

