// Steps «process chain»: an airy section — the title and intro on the left, then the steps as one
// connected timeline rather than tiles: a single rule runs across, each step hangs off it with its
// number inline with the title (flex items-baseline, ordinary digit), description indented under it.
// On mobile the rule turns vertical along the left edge. Motion: a calm fade-in, none if reduced.
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";

type StepsChainProps = {
  title: string;
  text?: string;
  items: string[];
};

export default function StepsChain({ title, text, items }: StepsChainProps) {
  const reduce = useReducedMotion();
  const fade = (i: number) =>
    reduce
      ? {}
      : {
          initial: { opacity: 0, y: 16 },
          whileInView: { opacity: 1, y: 0 },
          viewport: { once: true, amount: 0.4 },
          transition: { duration: 0.5, delay: i * 0.12, ease: "easeOut" as const },
        };

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <div className="max-w-text">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
            {text ? (
              <p className="mt-4 max-w-text text-lead text-pretty text-muted-foreground">{text}</p>
            ) : null}
          </div>

          <ol className="relative mt-16 md:mt-20">
            {/* the connecting rule: vertical on mobile, a single horizontal line on md+ */}
            <span
              aria-hidden="true"
              className="absolute bottom-3 left-4 top-3 w-px bg-border md:bottom-auto md:left-0 md:right-0 md:top-3 md:h-px md:w-auto"
            />
            <div className="flex flex-col gap-y-12 md:flex-row md:gap-0">
              {items.map((item, i) => (
                <m.li
                  key={item}
                  {...fade(i)}
                  className="relative min-w-0 flex-1 pl-14 md:pl-0 md:pr-8 md:last:pr-0"
                >
                  {/* the node on the rule, aligned with the number baseline */}
                  <span
                    aria-hidden="true"
                    className="absolute left-[9px] top-3 hidden h-2.5 w-2.5 rounded-full bg-primary ring-4 ring-background md:left-0 md:block"
                  />
                  <span
                    aria-hidden="true"
                    className="absolute left-[9px] top-3 h-2.5 w-2.5 rounded-full bg-primary ring-4 ring-background md:hidden"
                  />
                  <div className="flex items-baseline gap-3">
                    <span
                      aria-hidden="true"
                      className="shrink-0 font-display text-h2 font-bold leading-none text-primary tabular-nums md:bg-background md:pr-3"
                    >
                      {i + 1}
                    </span>
                    <h3 className="font-display text-h2 font-bold leading-tight text-balance wrap-break-word md:bg-background md:pr-3">
                      {item}
                    </h3>
                  </div>
                </m.li>
              ))}
            </div>
          </ol>
        </div>
      </section>
    </LazyMotion>
  );
}

