// Hero «split»: the offer on the left (title, subtitle, signal action), a light 3:2 room photo on the right;
// on phones the text comes first, the photo follows. Calm motion: fade-in entrance, tint on button hover.
import { srcSetOf, useFitWords } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type Link = { label: string; href: string };
type Image = { src: string; alt: string };

export type HeroProps = {
  title: string;
  subtitle?: string;
  button: Link;
  photo: Image;
  /** Place of the section in the page source: the build injects it (ui-kit.yaml#wz_id), never the composer. */
  wzId?: string;
};

const buttonClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-7 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

/** Entrance of the first screen (catalog E3): once, fade only, never with reduced motion or the still profile. */
function useEnter() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return (step: number) =>
    on
      ? {
          initial: { opacity: 0, y: 10 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.5, delay: step * 0.08, ease: [0.23, 1, 0.32, 1] as const },
