// FAQ «Вопрос и ответ»: спокойный блок вопросов-ответов — два столбца на широком экране,
// где слева заголовок, справа список раскрывающихся вопросов (native details/summary для доступности,
// движение — только мягкий fade появления через LazyMotion). Минимум визуального шума.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

export type FaqItem = {
  question: string;
  answer: string;
};

export type FaqProps = {
  title: string;
  items: FaqItem[];
};

export default function Faq({ title, items }: FaqProps) {
  const reduced = useReducedMotion();
  return (
    <section className="bg-card font-sans text-card-foreground">
      <LazyMotion features={domAnimation} strict>
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <div className="grid gap-x-12 gap-y-8 md:grid-cols-12">
            <div className="md:col-span-4">
              <m.h2
                initial={reduced ? false : { opacity: 0, y: 12 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.4 }}
                transition={{ duration: 0.5, ease: "easeOut" }}
                className="font-display text-h1 font-bold text-balance wrap-break-word"
              >
                {title}
              </m.h2>
            </div>
            <ul className="min-w-0 md:col-span-8">
              {items.map((item, i) => (
                <m.li
                  key={item.question}
                  initial={reduced ? false : { opacity: 0, y: 12 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true, amount: 0.3 }}
                  transition={{ duration: 0.4, delay: Math.min(i * 0.08, 0.3), ease: "easeOut" }}
                  className="border-b border-border first:border-t"
                >
                  <details className="group">
                    <summary className="flex min-h-11 cursor-pointer list-none items-baseline justify-between gap-6 py-5 [&::-webkit-details-marker]:hidden">
                      <h3 className="min-w-0 font-display text-h3 font-bold text-balance wrap-break-word">
                        {item.question}
                      </h3>
                      <span
                        aria-hidden="true"
                        className="shrink-0 font-display text-h3 font-bold text-muted-foreground transition-colors duration-200 group-open:text-primary group-hover:text-foreground"
                      >
                        +
                      </span>
                    </summary>
                    <p className="max-w-text pb-6 text-lead text-pretty text-muted-foreground">{item.answer}</p>
                  </details>
                </m.li>
              ))}
            </ul>
          </div>
        </div>
      </LazyMotion>
    </section>
  );
}

