// Final call-to-action: split grid — big display heading and phone number in large figures on the left,
// a light 3:2 photo of the reception desk on the right; the button dials the phone from props.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";
import { srcSetOf, IMAGE_WIDTHS } from "@wizard/ui-kit/v3/headless";

type Link = { label: string; href: string };
type Image = { src: string; alt: string };

export type CtaSectionProps = {
  title: string;
  phone: string;
  address: string;
  button: Link;
  photo: Image;
};

export default function CtaSection({ title, phone, address, button, photo }: CtaSectionProps) {
  const reduce = useReducedMotion();
  const fade = reduce
    ? {}
    : {
        initial: { opacity: 0, y: 12 },
        whileInView: { opacity: 1, y: 0 },
        viewport: { once: true, amount: 0.3 },
        transition: { duration: 0.5, ease: "easeOut" as const },
      };

  const buttonClass =
    "inline-flex min-h-11 items-center justify-center rounded-control bg-primary px-8 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

  return (
    <section className="bg-card font-sans text-card-foreground">
      <LazyMotion features={domAnimation}>
        <div className="mx-auto grid w-full max-w-page items-center gap-x-12 gap-y-10 px-gutter py-section lg:grid-cols-2">
          <m.div {...fade} className="order-1 min-w-0">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
            <a
              href={`tel:${phone.replace(/[^+\d]/g, "")}`}
              className="mt-6 block font-display text-hero font-bold tracking-tight text-foreground underline decoration-primary decoration-4 underline-offset-8 transition-colors duration-200 hover:decoration-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
            >
              {phone}
            </a>
            <p className="mt-5 text-lead text-pretty text-muted-foreground">{address}</p>
            <a href={button.href} className={`mt-8 ${buttonClass}`}>
              {button.label}
            </a>
          </m.div>
          <m.div
            {...(reduce
              ? {}
              : {
                  initial: { opacity: 0, y: 12 },
                  whileInView: { opacity: 1, y: 0 },
                  viewport: { once: true, amount: 0.3 },
                  transition: { duration: 0.6, delay: 0.1, ease: "easeOut" as const },
                })}
            className="order-2 min-w-0"
          >
            <img
              src={photo.src}
              srcSet={srcSetOf(photo.src, IMAGE_WIDTHS)}
              sizes="(min-width: 1024px) 50vw, 100vw"
              alt={photo.alt}
              className="aspect-3/2 w-full rounded-lg object-cover"
              loading="lazy"
            />
          </m.div>
        </div>
      </LazyMotion>
    </section>
  );
}

