// «Форма заявки» — плотная секция сразу после призыва: слева заголовок-пояснение,
// справа поле с кнопкой, в одной «карточке» на светлом фоне. Акцент signal — на кнопке.
import { useState } from "react";
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

export type FormProps = {
  title: string;
  intro: string;
  submitLabel: string;
};

export default function ServicesForm({ title, intro, submitLabel }: FormProps) {
  const [phone, setPhone] = useState("");
  const [sent, setSent] = useState(false);
  const reduce = useReducedMotion();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (phone.trim().length > 0) setSent(true);
  };

  return (
    <section className="bg-background font-sans text-foreground">
      <LazyMotion features={domAnimation}>
        <div className="mx-auto w-full max-w-page px-gutter pb-section">
          <m.div
            initial={reduce || sent ? false : { opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
            className="grid items-center gap-8 rounded-lg border border-border bg-card px-gutter py-12 text-card-foreground md:grid-cols-2 md:gap-12 md:py-16"
          >
            <div className="min-w-0">
              <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
              <p className="mt-4 max-w-text text-lead text-pretty text-muted-foreground">{intro}</p>
            </div>

            <form onSubmit={handleSubmit} className="min-w-0">
              <label htmlFor="services-form-phone" className="block text-small text-muted-foreground">
                Телефон
              </label>
              <div className="mt-2 flex flex-col gap-3 sm:flex-row">
                <input
                  id="services-form-phone"
                  name="phone"
                  type="tel"
                  autoComplete="tel"
                  required
                  value={phone}
                  onChange={(e) => {
                    setPhone(e.target.value);
                    setSent(false);
                  }}
                  placeholder="+7 (___) ___-__-__"
                  className="min-h-11 w-full min-w-0 flex-1 rounded-control border border-border bg-background px-4 text-body text-foreground placeholder:text-muted-foreground focus-visible:border-primary focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
                />
                <button
                  type="submit"
                  className="min-h-11 shrink-0 rounded-control bg-primary px-6 text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
                >
                  {submitLabel}
                </button>
              </div>
              {sent ? (
                <p className="mt-3 text-small text-muted-foreground" role="status">
                  Заявка отправлена — перезвоним в течение 15 минут.
                </p>
              ) : null}
            </form>
          </m.div>
        </div>
      </LazyMotion>
    </section>
  );
}

