Прошлый вариант секции:
```tsx
// How it works «appointment steps»: airy horizontal timeline — steps laid along one line, the number
// of each step drawn in code as a stroked SVG digit sitting on the line, large and calm (D-scheme light,
// calm motion). Title above, short texts under each step. Own composition, no cards.
export type HowProps = {
  title: string;
  items: string[];
};

// Digits 1–3 as stroked paths on a 24×32 grid — rendered by code, not a font, so they read as drawn.
const DIGIT_PATHS: Record<number, string> = {
  1: "M10 4 L4 9 M4 4 L4 28 L16 28",
  2: "M4 8 C4 4 8 2 12 2 C16 2 20 4 20 8 C20 12 16 15 4 28 L20 28",
  3: "M5 5 C7 3 10 2 13 2 C17 2 20 4 20 8 C20 12 17 14 14 14 C17 14 20 16 20 20 C20 25 17 28 13 28 C10 28 7 27 5 25",
};

function StepDigit({ value }: { value: number }) {
  return (
    <svg
      viewBox="0 0 24 32"
      className=""
      aria-hidden="true"
      className="h-14 w-auto stroke-primary md:h-20"
      fill="none"
      strokeWidth="2.5"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d={DIGIT_PATHS[value]} />
    </svg>
  );
}

export default function How({ title, items }: HowProps) {
  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <m.h2
            initial={{ opacity: 0, y: 12 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, amount: 0.5 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
            className="font-display text-h2 font-bold text-balance wrap-break-word"
          >
            {title}
          </m.h2>

          <ol className="relative mt-14 grid gap-y-12 md:mt-20 md:grid-cols-3 md:gap-x-10">
            {/* the horizontal line the steps sit on; a short stub on mobile */}
            <span
              aria-hidden="true"
              className="absolute left-0 top-7 hidden h-px w-full bg-border md:block"
            />
            <span aria-hidden="true" className="absolute left-0 top-7 h-px w-16 bg-border md:hidden" />

            {items.slice(0, 3).map((item, i) => (
              <m.li
                key={item}
                initial={{ opacity: 0, y: 12 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.4 }}
                transition={{ duration: 0.5, ease: "easeOut", delay: i * 0.1 }}
                className="relative pr-6 pl-0 md:pr-0 md:pl-0"
              >
                <div className="relative flex items-center bg-background pr-6 md:pr-10">
                  <StepDigit value={i + 1} />
                </div>
                <h3 className="sr-only">Шаг {i + 1}</h3>
                <p className="mt-5 max-w-text text-lead text-pretty text-foreground wrap-break-word">{item}</p>
              </m.li>
            ))}
          </ol>
        </div>
      </section>
    </LazyMotion>
  );
}

```
