// How it works «appointment steps»: airy vertical timeline — one rail on the left with the step
// number drawn in code as a stroked SVG digit sitting on the rail, large and calm; the step text
// sits beside it, each row with generous breathing room, indents shifting slightly so it reads
// as a descent rather than a grid (D-scheme light, calm motion). No cards, no columns of tiles.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

export type HowProps = {
  title: string;
  items: string[];
};

// Digits 1–3 as stroked paths on a 24×32 grid — rendered by code, not a font, so they read as drawn.
const DIGIT_PATHS: Record<number, string> = {
  1: "M10 4 L4 9 M4 4 L4 28 L16 28",
  2: "M4 8 C4 4 8 2 12 2 C16 2 20 4 20 8 C20 12 16 15 4 28 L20 28",
  3: "M5 5 C7 3 10 2 13 2 C17 2 20 4 20 8 C20 12 17 14 14 14 C17 14 20 16 20 20 C20 25 17 28 13 28 C10 28 7 27 5 25",
};

function StepDigit({ value }: { value: number }) {
  return (
    <svg
      viewBox="0 0 24 32"
      aria-hidden="true"
      className="h-12 w-auto shrink-0 stroke-primary sm:h-14 md:h-16"
      fill="none"
      strokeWidth="2.5"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d={DIGIT_PATHS[value]} />
    </svg>
  );
}

export default function How({ title, items }: HowProps) {
  const reduced = useReducedMotion();
  const fade = (delay: number) =>
    reduced
      ? {}
      : {
          initial: { opacity: 0, y: 12 },
          whileInView: { opacity: 1, y: 0 },
          viewport: { once: true, amount: 0.5 },
          transition: { duration: 0.5, ease: "easeOut" as const, delay },
        };

  const steps = items.slice(0, 3);

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <m.h2
            {...fade(0)}
            className="max-w-2xl font-display text-h2 font-bold text-balance wrap-break-word"
          >
            {title}
          </m.h2>

          <ol className="relative mt-14 md:mt-20">
            {/* the vertical rail the steps hang on */}
            <span
              aria-hidden="true"
              className="absolute top-4 bottom-4 left-6 w-px bg-border md:left-8"
            />

            {steps.map((item, i) => (
              <m.li
                key={item}
                {...fade(i * 0.1)}
                className="relative flex min-w-0 items-start gap-6 pl-0 md:gap-10 md:pl-0"
              >
                {/* digit sits on the rail, breaking the line with a background patch */}
                <span className="relative z-1 flex shrink-0 items-center bg-background py-2 pr-2 md:pr-4">
                  <StepDigit value={i + 1} />
                </span>

                {/* text drifts right on later steps — a quiet descent, not a grid */}
                <div className={`min-w-0 pb-12 md:pb-16 ${i === 1 ? "md:ml-12" : i === 2 ? "md:ml-24" : ""}`}>
                  <h3 className="font-display text-h3 font-bold text-foreground wrap-break-word">
                    Шаг {i + 1}
                  </h3>
                  <p className="mt-3 max-w-text text-lead text-pretty text-muted-foreground wrap-break-word">
                    {item}
                  </p>
                </div>
              </m.li>
            ))}
          </ol>
        </div>
      </section>
    </LazyMotion>
  );
}

