// FAQ «questions & answers»: a calm split section — the title sits quietly in a narrow
// left column, the questions unfold in a wider right column as gentle collapsible rows
// (native details/summary keeps it dependable and accessible); answers answer the fear
// of pain directly, with no decoration beyond a soft rule and a quiet hover tint.
type FaqItem = {
  question: string;
  answer: string;
};

export type FaqProps = {
  title: string;
  items: FaqItem[];
};

const summaryClass =
  "flex min-h-11 cursor-pointer list-none items-baseline justify-between gap-6 py-5 font-display text-h3 font-bold text-balance wrap-break-word transition-colors duration-200 hover:text-primary [&::-webkit-details-marker]:hidden focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

export default function Faq({ title, items }: FaqProps) {
  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-x-16 gap-y-10 lg:grid-cols-12">
          <div className="lg:col-span-4">
            <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
          </div>
          <div className="min-w-0 lg:col-span-8">
            <ul className="border-t border-border">
              {items.map((item) => (
                <li key={item.question} className="border-b border-border">
                  <details className="group">
                    <summary className={summaryClass}>
                      <span className="min-w-0">{item.question}</span>
                      <span
                        aria-hidden="true"
                        className="shrink-0 font-sans text-body font-bold text-primary transition-transform duration-300 group-open:rotate-45"
                      >
                        +
                      </span>
                    </summary>
                    <p className="max-w-text pb-6 text-lead text-pretty text-muted-foreground">{item.answer}</p>
                  </details>
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>
    </section>
  );
}

