// Steps «process strip»: an airy single band of three steps, no photos — the number is drawn by code on one
// baseline with the step title (flex items-baseline), the description sits under the title with the same indent;
// thin hairline rules separate the columns, motion is a calm fade on entry.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type Step = {
  title: string;
  text: string;
};

export type StepsProps = {
  title: string;
  items: Step[];
};

export default function Steps({ title, items }: StepsProps) {
  const reduced = useReducedMotion();

  return (
    <LazyMotion features={domAnimation} strict>
      <section className="bg-card font-sans text-card-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <h2 className="max-w-text font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>

          <ol className="mt-10 grid gap-10 border-t border-border pt-10 sm:grid-cols-1 lg:grid-cols-3 lg:gap-0 lg:divide-x lg:divide-border">
            {items.map((step, i) => (
              <m.li
                key={step.title}
                className="min-w-0 lg:px-gutter lg:first:pl-0 lg:last:pr-0"
                initial={reduced ? false : { opacity: 0, y: 12 }}
                whileInView={reduced ? undefined : { opacity: 1, y: 0 }}
                viewport={{ once: true, margin: "-80px" }}
                transition={{ duration: 0.5, delay: reduced ? 0 : i * 0.12, ease: "easeOut" }}
              >
                <div className="flex items-baseline gap-3">
                  <span
                    aria-hidden="true"
                    className="shrink-0 font-display text-h2 font-bold tabular-nums text-primary"
                  >
                    {i + 1}
                  </span>
                  <h3 className="min-w-0 font-display text-h3 font-bold text-balance wrap-break-word">
                    {step.title}
                  </h3>
                </div>
                <p className="mt-3 pl-[calc(1ch+0.75rem)] text-body text-pretty text-muted-foreground wrap-break-word lg:pl-9">
                  {step.text}
                </p>
              </m.li>
            ))}
          </ol>
        </div>
      </section>
    </LazyMotion>
  );
}

