// Comfort / trust points: dense section on a card contrast after the catalog —
// big title locked to the left column, three factual points as ruled rows on the right
// with tab-stable rhythm, and the photo of the doctor at the screen sitting under the
// title in 3:2. One idea: calm, evidence-based trust. Own composition.
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { srcSetOf } from "@wizard/ui-kit/v3/headless";

type Point = { title: string; text?: string };

export type ComfortProps = {
  title: string;
  items: Point[];
  photo?: { src: string; alt: string };
};

export default function Comfort({ title, items, photo }: ComfortProps) {
  const reduced = useReducedMotion();
  const fade = reduced || undefined
    ? {}
    : {
        initial: { opacity: 0, y: 12 },
        whileInView: { opacity: 1, y: 0 },
        viewport: { once: true, amount: 0.3 },
        transition: { duration: 0.5, ease: "easeOut" as const },
      };

  return (
    <section className="bg-card font-sans text-card-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-x-12 gap-y-10 lg:grid-cols-2 lg:gap-y-0">
          <m.div {...fade} className="min-w-0">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
            {photo ? (
              <figure className="mt-8 min-w-0">
                <img
                  src={photo.src}
                  srcSet={srcSetOf(photo.src)}
                  alt={photo.alt}
                  loading="lazy"
                  className="aspect-3/2 w-full rounded-lg object-cover"
                />
              </figure>
            ) : null}
          </m.div>

          <div className="flex min-w-0 flex-col justify-center">
            <ul className="border-t border-border">
              {items.map((item, i) => (
                <m.li
                  key={item.title}
                  {...(reduced
                    ? {}
                    : {
                        initial: { opacity: 0, y: 12 },
                        whileInView: { opacity: 1, y: 0 },
                        viewport: { once: true, amount: 0.5 },
                        transition: { duration: 0.45, delay: i * 0.08, ease: "easeOut" as const },
                      })}
                  className="border-b border-border py-6 last:border-b-0 md:py-8"
                >
                  <div className="flex items-baseline gap-3">
                    <span
                      aria-hidden="true"
                      className="shrink-0 font-display text-h3 font-bold text-primary tabular-nums"
                    >
                      {String(i + 1).padStart(2, "0")}
                    </span>
                    <h3 className="min-w-0 font-display text-h3 font-bold text-balance wrap-break-word">
                      {item.title}
                    </h3>
                  </div>
                  {item.text ? (
                    <p className="mt-2 max-w-text pl-0 text-body text-pretty text-muted-foreground md:pl-9">
                      {item.text}
                    </p>
