// Steps «process strip»: airy band, no photos. Asymmetric split layout — the heading sits in a narrow left
// column (sticky on tall screens), the three steps stack on the right as rows of a list separated by thin
// hairline rules; the step number is drawn by code on one baseline with the step title (flex items-baseline),
// the description sits under the title with the same indent. Calm fade on entry, no animation if reduced.
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type Step = {
  title: string;
  text: string;
};

export type StepsProps = {
  title: string;
  items: Step[];
};

export default function Steps({ title, items }: StepsProps) {
  const reduced = useReducedMotion();

  return (
    <LazyMotion features={domAnimation} strict>
      <section className="bg-card font-sans text-card-foreground">
        <div className="mx-auto grid w-full max-w-page grid-cols-1 gap-x-gutter gap-y-10 px-gutter py-section lg:grid-cols-12 lg:gap-y-0">
          <div className="lg:col-span-4 lg:pt-2">
            <h2 className="max-w-text font-display text-h2 font-bold text-balance wrap-break-word lg:sticky lg:top-24">
              {title}
            </h2>
          </div>

          <ol className="min-w-0 lg:col-span-8 lg:col-start-5">
            {items.map((step, i) => (
              <m.li
                key={step.title}
                className="min-w-0 border-t border-border py-8 lg:py-10 lg:last:border-b"
                initial={reduced ? false : { opacity: 0, y: 12 }}
                whileInView={reduced ? undefined : { opacity: 1, y: 0 }}
                viewport={{ once: true, margin: "-80px" }}
                transition={{ duration: 0.5, delay: reduced ? 0 : i * 0.1, ease: "easeOut" }}
              >
                <div className="flex items-baseline gap-3">
                  <span
                    aria-hidden="true"
                    className="shrink-0 font-display text-h2 font-bold tabular-nums text-primary"
                  >
                    {i + 1}
                  </span>
                  <h3 className="min-w-0 font-display text-h3 font-bold text-balance wrap-break-word">
                    {step.title}
                  </h3>
                </div>
                <p className="mt-3 max-w-text pl-9 text-body text-pretty text-muted-foreground wrap-break-word">
                  {step.text}
                </p>
              </m.li>
            ))}
          </ol>
        </div>
      </section>
    </LazyMotion>
  );
}

import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";

export default function Hero({
  badge,
  headline,
  sub,
  ctaPrimary,
  ctaSecondary,
  primaryHref,
  secondaryHref,
  photo,
}) {
  const reduce = useReducedMotion();
  const [ready, setReady] = useState(false);
  const ref = useRef(null);
  useEffect(() => setReady(true), []);

  const fade = (delay) =>
    reduce
      ? {}
      : ready
        ? { initial: { opacity: 0, y: 16 }, animate: { opacity: 1, y: 0 }, transition: { duration: 0.6, delay, ease: "easeOut" } }
        : { animate: { opacity: 1 } };

  return (
    <LazyMotion features={domAnimation} strict>
      <section id="hero" ref={ref} className="relative overflow-hidden bg-background py-section">
        <div className="mx-auto grid max-w-page items-center gap-10 px-gutter lg:grid-cols-2 lg:gap-16">
          <div className="min-w-0">
            <m.p {...fade(0)} className="text-small text-muted-foreground">
              {badge}
            </m.p>
            <m.h1
              {...fade(0.1)}
              className="mt-4 font-display text-hero leading-tight text-foreground wrap-break-word"
            >
              {headline}
            </m.h1>
            <m.p {...fade(0.2)} className="mt-6 max-w-text text-lead text-muted-foreground wrap-break-word">
              {sub}
            </m.p>
            <m.div {...fade(0.3)} className="mt-8 flex flex-wrap gap-4">
              <a
                href={primaryHref}
                className="inline-flex min-h-11 items-center rounded-control bg-primary px-6 py-3 font-sans text-body font-semibold text-primary-foreground transition-colors hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
              >
                {ctaPrimary}
              </a>
              <a
                href={secondaryHref}
                className="inline-flex min-h-11 items-center rounded-control border border-border bg-card px-6 py-3 font-sans text-body font-semibold text-card-foreground transition-colors hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
              >
                {ctaSecondary}
              </a>
            </m.div>
          </div>
          <m.div
            {...fade(0.25)}
            className="relative min-w-0"
          >
            <div className="overflow-hidden rounded-lg">
              <img
                src={photo.src}
                alt={photo.alt}
                className="aspect-3/2 w-full object-cover"
                loading="eager"
              />
            </div>
            <div className="absolute -bottom-4 left-4 hidden rounded-md bg-card px-5 py-4 text-card-foreground shadow-sm sm:block">
              <p className="font-display text-h3">Онлайн-заявка</p>
              <p className="mt-1 font-sans text-small text-muted-foreground">
                Администратор перезвонит и подтвердит запись
              </p>
            </div>
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

