// Steps «Как проходит запись»: airy section after the dense catalog —
// a large h2 on the left of a split grid, three steps laid out horizontally
// with numbers inline with headings (flex items-baseline) and descriptions
// aligned under them; calm fade-in entrance, tabular step numbers in signal accent.
type Step = {
  title: string;
  text: string;
};

export type StepsSectionProps = {
  title: string;
  items: Step[];
};

import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

export default function StepsSection({ title, items }: StepsSectionProps) {
  const reduce = useReducedMotion();

  const fade = (i: number) =>
    reduce
      ? {}
      : {
          initial: { opacity: 0, y: 16 },
          whileInView: { opacity: 1, y: 0 },
          viewport: { once: true, amount: 0.4 },
          transition: { duration: 0.6, delay: i * 0.12, ease: "easeOut" as const },
        };

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-10 lg:grid-cols-12 lg:gap-8">
          <h2 className="font-display text-h1 font-bold text-balance wrap-break-word lg:col-span-4">
            {title}
          </h2>
          <ol className="grid min-w-0 gap-10 sm:grid-cols-3 sm:gap-8 lg:col-span-8">
            {items.map((step, i) => (
              <li key={step.title} className="flex min-w-0 flex-col border-t-2 border-border pt-6">
                <m.div {...fade(i)} className="flex min-w-0 flex-col">
                  <div className="flex items-baseline gap-3">
                    <span
                      aria-hidden="true"
                      className="shrink-0 font-display text-h2 font-bold tabular-nums text-primary"
                    >
                      {i + 1}
                    </span>
                    <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">
                      {step.title}
                    </h3>
                  </div>
                  <p className="mt-3 max-w-text pl-9 text-body text-pretty text-muted-foreground">
                    {step.text}
                  </p>
                </m.div>
              </li>
            ))}
          </ol>
        </div>
      </div>
    </section>
  );
}

