import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type Step = {
  title: string;
  text: string;
};

export type StepsProps = {
  title: string;
  items: Step[];
};

export default function Steps({ title, items }: StepsProps) {
  const reduce = useReducedMotion();

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>

        <LazyMotion features={domAnimation}>
          <ol className="mt-12 grid gap-10 md:grid-cols-3 md:gap-8">
            {items.map((step, i) => (
              <m.li
                key={step.title}
                initial={reduce ? false : { opacity: 0, y: 16 }}
                whileInView={reduce ? undefined : { opacity: 1, y: 0 }}
                viewport={{ once: true, margin: "-80px" }}
                transition={{ duration: 0.5, delay: i * 0.12, ease: "easeOut" }}
                className="min-w-0 border-t-2 border-foreground pt-6"
              >
                <div className="flex items-baseline gap-3">
                  <span
                    aria-hidden="true"
                    className="shrink-0 font-display text-h3 font-bold tabular-nums text-primary"
                  >
                    {i + 1}
                  </span>
                  <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">
                    {step.title}
                  </h3>
                </div>
                <p className="mt-3 max-w-text text-body text-muted-foreground md:pl-[calc(1.5rem+0.75rem)]">
                  {step.text}
                </p>
              </m.li>
            ))}
          </ol>
        </LazyMotion>
      </div>
    </section>
  );
}

