import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";
import { srcSetOf, IMAGE_WIDTHS } from "@wizard/ui-kit/v3/headless";

type CtaProps = {
  title: string;
  cta: string;
  photo: string;
  photoAlt: string;
};

export default function Cta({ title, cta, photo, photoAlt }: CtaProps) {
  const reduce = useReducedMotion();

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-card font-sans text-card-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <div className="grid items-stretch overflow-hidden rounded-lg border border-border bg-background md:grid-cols-2">
            <div className="relative min-h-64 md:min-h-full">
              <img
                src={srcSetOf(photo, IMAGE_WIDTHS)}
                alt={photoAlt}
                className="absolute inset-0 h-full w-full object-cover"
              />
            </div>
            <div className="flex flex-col justify-center gap-6 p-8 md:p-12 lg:p-16">
              <m.h2
                initial={reduce ? false : { opacity: 0, y: 12 }}
                whileInView={reduce ? undefined : { opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.4 }}
                transition={{ duration: 0.5, ease: "easeOut" }}
                className="font-display text-h2 font-bold text-balance wrap-break-word"
              >
                {title}
              </m.h2>
              <m.div
                initial={reduce ? false : { opacity: 0, y: 12 }}
                whileInView={reduce ? undefined : { opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.4 }}
                transition={{ duration: 0.5, ease: "easeOut", delay: 0.1 }}
              >
                <a
                  href="tel:+7 900 000-00-00"
                  className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-8 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
                >
                  {cta}
                </a>
              </m.div>
            </div>
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}

