import { useState } from "react";
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type FaqItem = {
  question: string;
  answer: string;
};

export type FaqProps = {
  title: string;
  items: FaqItem[];
};

export default function Faq({ title, items }: FaqProps) {
  const [open, setOpen] = useState<number | null>(0);
  const reduce = useReducedMotion();

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="max-w-3xl">
          <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
        </div>

        <LazyMotion features={domAnimation}>
          <ul className="mt-12 max-w-3xl divide-y divide-border border-y border-border">
            {items.map((item, i) => {
              const isOpen = open === i;
              return (
                <li key={item.question}>
                  <button
                    type="button"
                    onClick={() => setOpen(isOpen ? null : i)}
                    aria-expanded={isOpen}
                    className="flex min-h-11 w-full items-baseline justify-between gap-6 py-6 text-left focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
                  >
                    <span className="font-display text-h3 font-bold text-balance wrap-break-word">
                      {item.question}
                    </span>
                    <m.span
                      aria-hidden="true"
                      className="shrink-0 font-display text-h3 font-bold text-primary"
                      animate={reduce ? undefined : { rotate: isOpen ? 45 : 0 }}
                      transition={{ duration: 0.2, ease: "easeOut" }}
                    >
                      +
                    </m.span>
                  </button>
                  <m.div
                    initial={false}
                    animate={
                      reduce
                        ? undefined
                        : { height: isOpen ? "auto" : 0, opacity: isOpen ? 1 : 0 }
                    }
                    transition={{ duration: 0.25, ease: "easeOut" }}
                    className="overflow-hidden"
                  >
                    <p className="max-w-text pb-6 text-body text-pretty text-muted-foreground">
                      {item.answer}
                    </p>
                  </m.div>
                </li>
              );
            })}
          </ul>
        </LazyMotion>
      </div>
    </section>
  );
}

