import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";
import { srcSetOf, IMAGE_WIDTHS } from "@wizard/ui-kit/v3/headless";

type ContactsProps = {
  title: string;
  phone: string;
  phoneHref: string;
  address: string;
  photo: string;
  photoAlt: string;
};

export default function Contacts({ title, phone, phoneHref, address, photo, photoAlt }: ContactsProps) {
  const reduceMotion = useReducedMotion();

  const phoneLinkClass =
    "inline-flex min-h-11 items-center font-display text-h3 font-bold text-foreground underline decoration-signal decoration-2 underline-offset-8 transition-colors duration-200 hover:text-signal focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-card font-sans text-card-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <div className="grid gap-10 md:grid-cols-12 md:items-center md:gap-14">
            <m.div
              className="min-w-0 md:col-span-6"
              initial={reduceMotion ? false : { opacity: 0, y: 16 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-80px" }}
              transition={{ duration: 0.5, ease: "easeOut" }}
            >
              <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>

              <div className="mt-8 space-y-6 border-t-2 border-border pt-8">
                <div>
                  <p className="text-small text-muted-foreground">Телефон</p>
                  <a href={phoneHref} className={`mt-1 ${phoneLinkClass}`}>
                    {phone}
                  </a>
                </div>
                <div>
                  <p className="text-small text-muted-foreground">Адрес</p>
                  <p className="mt-1 font-display text-h3 font-bold text-foreground wrap-break-word">{address}</p>
                </div>
              </div>
            </m.div>

            <m.div
              className="min-w-0 md:col-span-6"
              initial={reduceMotion ? false : { opacity: 0, y: 16 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-80px" }}
              transition={{ duration: 0.5, ease: "easeOut", delay: 0.1 }}
            >
              <img
                src={photo}
                srcSet={srcSetOf(photo, IMAGE_WIDTHS)}
                alt={photoAlt}
                loading="lazy"
                className="aspect-[3/2] w-full rounded-lg object-cover"
              />
            </m.div>
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}

