import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type Step = {
  title: string;
  text: string;
};

export type StepsProps = {
  title: string;
  items: Step[];
};

export default function Steps({ title, items }: StepsProps) {
  const reduceMotion = useReducedMotion();

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-10 lg:grid-cols-12 lg:gap-8">
          <div className="lg:col-span-4">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
          </div>

          <LazyMotion features={domAnimation}>
            <ol className="min-w-0 lg:col-span-8">
              {items.map((step, i) => (
                <m.li
                  key={step.title}
                  initial={reduceMotion ? false : { y: 16 }}
                  whileInView={reduceMotion ? undefined : { opacity: 1, y: 0 }}
                  viewport={{ once: true, margin: "-80px" }}
                  transition={{ duration: 0.5, delay: reduceMotion ? 0 : i * 0.12, ease: "easeOut" }}
                  className="grid gap-x-8 gap-y-3 border-t border-border py-8 first:border-t-0 first:pt-0 last:pb-0 md:grid-cols-12 md:items-baseline"
                >
                  <div className="flex min-w-0 items-baseline gap-3 md:col-span-5">
                    <span className="shrink-0 font-display text-h3 font-bold text-primary tabular-nums">
                      {i + 1}
                    </span>
                    <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                  </div>
                  <p className="min-w-0 max-w-text text-body text-pretty text-muted-foreground md:col-span-7">
                    {step.text}
                  </p>
                </m.li>
              ))}
            </ol>
          </LazyMotion>
        </div>
      </div>
    </section>
  );
}

import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

export default function Hero({ headline, lead, ctaLabel, ctaHref, secondaryLabel, secondaryHref, image, imageAlt, stats }) {
  const reduce = useReducedMotion();

  const fade = reduce
    ? {}
    : {
        initial: { opacity: 0, y: 16 },
        animate: { opacity: 1, y: 0 },
        transition: { duration: 0.6, ease: "easeOut" },
      };

  const fadeDelay = (delay) =>
    reduce
      ? {}
      : {
          initial: { opacity: 0, y: 16 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.6, ease: "easeOut", delay },
        };

  return (
    <LazyMotion features={domAnimation}>
      <section id="hero" className="bg-background text-foreground">
        <div className="mx-auto max-w-page px-gutter py-section">
          <div className="grid gap-10 lg:grid-cols-12 lg:items-center">
            <div className="min-w-0 lg:col-span-6">
              <m.h1
                {...fade}
                className="font-display text-hero leading-tight wrap-break-word"
              >
                {headline}
              </m.h1>

              <m.p
                {...fadeDelay(0.1)}
                className="mt-6 max-w-text text-lead text-muted-foreground"
              >
                {lead}
              </m.p>

              <m.div
                {...fadeDelay(0.2)}
                className="mt-8 flex flex-wrap items-center gap-3"
              >
                <a
                  href={ctaHref}
                  className="inline-flex min-h-11 items-center justify-center rounded-control bg-primary px-6 text-body font-medium text-primary-foreground transition-colors hover:opacity-90"
                >
                  {ctaLabel}
                </a>
                <a
                  href={secondaryHref}
                  className="inline-flex min-h-11 items-center justify-center rounded-control border border-border px-6 text-body font-medium text-foreground transition-colors hover:bg-muted"
                >
                  {secondaryLabel}
                </a>
              </m.div>

              <m.dl
                {...fadeDelay(0.3)}
                className="mt-12 grid grid-cols-3 gap-6 border-t border-border pt-8"
              >
                {stats.map((s) => (
                  <div key={s.value} className="min-w-0">
                    <dt className="text-small text-muted-foreground">{s.label}</dt>
                    <dd className="mt-1 font-display text-h3">{s.value}</dd>
                  </div>
                ))}
              </m.dl>
            </div>

            <m.div
              {...fadeDelay(0.2)}
              className="min-w-0 lg:col-span-6"
            >
              <img
                src={image}
                alt={imageAlt}
                className="aspect-[3/2] w-full rounded-lg object-cover"
                loading="eager"
              />
            </m.div>
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}

