type HowItWorksProps = {
  title: string;
  items: string[];
};

const steps = [
  {
    number: "1",
    title: "Заявка",
    text: "Оставьте заявку на сайте или по телефону — администратор зафиксирует удобное время и пожелания.",
  },
  {
    number: "2",
    title: "Звонок администратора",
    text: "В течение 15 минут администратор перезвонит, подтвердит запись и ответит на вопросы.",
  },
  {
    number: "3",
    title: "Приём",
    text: "Приходите в назначенное время — специалист проведёт приём и составит план дальнейших действий.",
  },
];

export default function HowItWorks({ title, items }: HowItWorksProps) {
  const shouldReduceMotion = useReducedMotion();

  const content = steps.map((step, index) => {
    const label = items[index] ?? step.title;
    return { ...step, title: label };
  });

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-card font-sans text-card-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>

          <ol className="mt-10 grid gap-8 border-t-2 border-foreground pt-8 md:grid-cols-3 md:gap-10">
            {content.map((step, index) => (
              <m.li
                key={step.number}
                initial={shouldReduceMotion ? false : { opacity: 0, y: 16 }}
                whileInView={shouldReduceMotion ? undefined : { opacity: 1, y: 0 }}
                viewport={{ once: true, margin: "-80px" }}
                transition={{ duration: 0.5, delay: index * 0.12, ease: "easeOut" }}
                className="min-w-0"
              >
                <div className="flex items-baseline gap-3">
                  <span
                    aria-hidden="true"
                    className="font-display text-hero font-bold leading-none text-primary tabular-nums shrink-0"
                  >
                    {step.number}
                  </span>
                  <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                </div>
                <p className="mt-3 max-w-text text-body text-muted-foreground">{step.text}</p>
              </m.li>
            ))}
          </ol>
        </div>
      </section>
    </LazyMotion>
  );
}

