type ContactsProps = {
  title: string;
  phone: string;
  address: string;
  photo: string;
  photoAlt: string;
};

export default function Contacts({ title, phone, address, photo, photoAlt }: ContactsProps) {
  const reduce = useReducedMotion();

  const phoneHref = `tel:${phone.replace(/[^+\d]/g, "")}`;

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-inverse font-sans text-inverse-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <div className="grid gap-10 md:grid-cols-2 md:items-stretch">
            <m.div
              className="flex min-w-0 flex-col justify-between gap-10"
              {...(reduce
                ? {}
                : {
                    initial: { opacity: 0, y: 16 },
                    whileInView: { opacity: 1, y: 0 },
                    viewport: { once: true, margin: "-80px" },
                    transition: { duration: 0.5, ease: "easeOut" },
                  })}
            >
              <div className="min-w-0">
                <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
                <dl className="mt-8 space-y-6">
                  <div className="min-w-0">
                    <dt className="text-small text-inverse-foreground/70">Телефон</dt>
                    <dd className="mt-1">
                      <a
                        href={phoneHref}
                        className="inline-flex min-h-11 min-w-11 items-center font-display text-h3 font-bold text-inverse-foreground underline decoration-primary decoration-2 underline-offset-4 transition-colors duration-200 hover:decoration-inverse-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
                      >
                        {phone}
                      </a>
                    </dd>
                  </div>
                  <div className="min-w-0">
                    <dt className="text-small text-inverse-foreground/70">Адрес</dt>
                    <dd className="mt-1 text-lead text-pretty wrap-break-word">{address}</dd>
                  </div>
                </dl>
              </div>
              <a
                href={phoneHref}
                className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
              >
                Позвонить
              </a>
            </m.div>

            <m.div
              className="min-w-0"
              {...(reduce
                ? {}
                : {
                    initial: { opacity: 0, y: 16 },
                    whileInView: { opacity: 1, y: 0 },
                    viewport: { once: true, margin: "-80px" },
                    transition: { duration: 0.5, ease: "easeOut", delay: 0.1 },
                  })}
            >
              <img
                src={photo}
                srcSet={srcSetOf(photo, IMAGE_WIDTHS)}
                alt={photoAlt}
                loading="lazy"
                className="aspect-[3/2] w-full rounded-lg object-cover"
              />
            </m.div>
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}

