import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

export type StepsProps = {
  title: string;
  items: string[];
};

export default function Steps({ title, items }: StepsProps) {
  const reduce = useReducedMotion();

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
        <LazyMotion features={domAnimation}>
          <ol className="mt-12 grid gap-10 sm:grid-cols-3 sm:gap-8">
            {items.map((step, i) => (
              <m.li
                key={step}
                initial={reduce ? false : { opacity: 0, y: 16 }}
                whileInView={reduce ? undefined : { opacity: 1, y: 0 }}
                viewport={{ once: true, margin: "-80px" }}
                transition={{ duration: 0.5, delay: reduce ? 0 : i * 0.12, ease: "easeOut" }}
                className="min-w-0 border-t-2 border-foreground pt-6"
              >
                <p
                  aria-hidden="true"
                  className="font-display text-hero font-bold leading-none text-primary tabular-nums"
                >
                  {String(i + 1).padStart(2, "0")}
                </p>
                <p className="mt-4 max-w-text text-body text-pretty text-muted-foreground wrap-break-word">
                  {step}
                </p>
              </m.li>
            ))}
          </ol>
        </LazyMotion>
      </div>
    </section>
  );
}

