import { useState } from "react";
import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

type FaqItem = {
  question: string;
  answer: string;
};

export type FaqProps = {
  title: string;
  items: FaqItem[];
};

export default function Faq({ title, items }: FaqProps) {
  const [open, setOpen] = useState<number | null>(0);
  const reduce = useReducedMotion();

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-10 lg:grid-cols-12 lg:gap-16">
          <div className="lg:col-span-4">
            <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
          </div>
          <div className="min-w-0 lg:col-span-8">
            <ul className="border-t border-border">
              {items.map((item, i) => {
                const isOpen = open === i;
                return (
                  <li key={item.question} className="border-b border-border">
                    <button
                      type="button"
                      onClick={() => setOpen(isOpen ? null : i)}
                      aria-expanded={isOpen}
                      aria-controls={`faq-panel-${i}`}
                      className="flex min-h-11 w-full items-center justify-between gap-6 py-6 text-left focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
                    >
                      <span className="font-display text-h3 font-bold text-balance wrap-break-word">
                        {item.question}
                      </span>
                      <span
                        aria-hidden="true"
                        className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-control border border-border text-h3 font-bold transition-colors duration-200 ${
                          isOpen ? "bg-primary text-primary-foreground" : "text-muted-foreground"
                        }`}
                      >
                        {isOpen ? "−" : "+"}
                      </span>
                    </button>
                    <LazyMotion features={domAnimation}>
                      <m.div
                        id={`faq-panel-${i}`}
                        initial={false}
                        animate={{ height: isOpen ? "auto" : 0, opacity: isOpen ? 1 : 0 }}
                        transition={{ duration: reduce ? 0 : 0.25, ease: "easeOut" }}
                        className="overflow-hidden"
                      >
                        <p className="max-w-text pb-6 text-body text-pretty text-muted-foreground">
                          {item.answer}
                        </p>
                      </m.div>
                    </LazyMotion>
                  </li>
                );
              })}
            </ul>
          </div>
        </div>
      </div>
    </section>
  );
}

